<?php
declare(strict_types=1);
namespace CommunityHub;
final class Training {
 public static function complete(array $actor,int $training,int $registration,array $d):void{$result=$d['result_status']??'';if(!in_array($result,['passed','failed','incomplete'],true))throw new HttpError('Select passed, failed or incomplete.');$score=isset($d['score'])&&$d['score']!==''?$d['score']:null;if($score!==null&&(!is_numeric($score)||!is_finite((float)$score)||(float)$score<0||(float)$score>100))throw new HttpError('Score must be between 0 and 100.');$score=$score!==null?(float)$score:null;$notes=App::text($d['instructor_notes']??'','Instructor notes',10000,true)?:null;App::transaction(function()use($actor,$training,$registration,$result,$score,$notes){$r=App::row('SELECT r.*,t.title,t.department_id FROM training_registrations r JOIN training_sessions t ON t.id=r.training_id WHERE r.id=? AND r.training_id=? FOR UPDATE',[$registration,$training]);if(!$r)throw new HttpError('Registration not found.',404);$attendance=$result==='incomplete'?'no_show':'attended';App::query('UPDATE training_registrations SET status=?,result_status=?,score=?,instructor_notes=?,completed_by=?,completed_at=NOW() WHERE id=?',[$attendance,$result,$score,$notes,$actor['id'],$registration]);$history=App::insert('INSERT INTO training_completion_history(training_id,user_id,registration_id,result_status,score,instructor_notes,completed_by) VALUES(?,?,?,?,?,?,?)',[$training,$r['user_id'],$registration,$result,$score,$notes,$actor['id']]);if($result==='passed')self::progress($training,(int)$r['user_id'],$history,$score,(int)$actor['id']);Automation::emit('training_completed',['entity_type'=>'training','entity_id'=>$training,'subject_user_id'=>(int)$r['user_id'],'training_id'=>$training,'registration_id'=>$registration,'title'=>$r['title'],'department_id'=>$r['department_id'],'registration_type'=>$r['registration_type'],'status'=>$attendance,'result_status'=>$result,'score'=>$score],(int)$actor['id']);});}
 public static function progress(int $training,int $user,int $history,?float $score,int $actor):void{$rules=App::rows('SELECT r.*,c.name certification_name,c.expires_after_days FROM training_certification_rules r LEFT JOIN certifications c ON c.id=r.certification_id WHERE r.training_id=? AND r.is_enabled=1 ORDER BY r.id',[$training]);foreach($rules as $r){$log=function(string $status,string $detail,?int $cert=null)use($r,$training,$user,$history){App::query('INSERT INTO training_rule_execution_log(rule_id,training_id,user_id,completion_history_id,certification_id,result_status,detail) VALUES(?,?,?,?,?,?,?)',[$r['id'],$training,$user,$history,$cert,$status,$detail]);};if($r['minimum_score']!==null&&($score===null||$score<(float)$r['minimum_score'])){$log('skipped','Minimum score '.$r['minimum_score'].' not met.');continue;}try{$parts=[];if($r['certification_id']){$days=$r['expires_after_days']?:null;App::query('INSERT INTO user_certifications(user_id,certification_id,awarded_by,awarded_at,expires_at,notes) VALUES(?,?,?,NOW(),IF(? IS NULL,NULL,DATE_ADD(NOW(),INTERVAL ? DAY)),?) ON DUPLICATE KEY UPDATE awarded_by=VALUES(awarded_by),awarded_at=NOW(),expires_at=VALUES(expires_at),notes=VALUES(notes)',[$user,$r['certification_id'],$actor,$days,$days,'Awarded automatically after passing training #'.$training]);$log('awarded','Awarded '.$r['certification_name'],(int)$r['certification_id']);$parts[]=$r['certification_name'].' awarded';}if($r['advance_recruit_stage']){$u=App::row('SELECT department_id FROM users WHERE id=?',[$user]);App::query('INSERT INTO recruit_pipeline(user_id,department_id,stage,notes,changed_by) VALUES(?,?,?,?,?)',[$user,$u['department_id'],$r['advance_recruit_stage'],'Advanced automatically after passing training #'.$training,$actor]);if($r['advance_recruit_stage']==='recruit')App::query("UPDATE users SET role='recruit',member_status='recruit' WHERE id=?",[$user]);if($r['advance_recruit_stage']==='member')App::query("UPDATE users SET role='member',member_status='active',joined_department_at=COALESCE(joined_department_at,NOW()) WHERE id=?",[$user]);$log('progressed','Recruit pipeline advanced to '.$r['advance_recruit_stage']);$parts[]='Progressed to '.$r['advance_recruit_stage'];}if($r['complete_probation']){App::query("UPDATE staff_profiles SET probation_status='completed',probation_ends_at=COALESCE(probation_ends_at,NOW()),updated_by=? WHERE user_id=?",[$actor,$user]);App::query("INSERT INTO staff_actions(user_id,action_type,reason,performed_by) VALUES(?,'probation_complete',?,?)",[$user,'Completed automatically after passing training #'.$training,$actor]);$log('completed_probation','Probation marked completed.');$parts[]='Probation completed';}if($r['notify_member']&&$parts)App::query('INSERT INTO notifications(user_id,title,message,url) VALUES(?,?,?,?)',[$user,'Training progression',implode(' · ',$parts),'/personnel/'.$user]);}catch(\Throwable $e){$log('failed','Progression action failed. Check the rule configuration.',isset($r['certification_id'])?(int)$r['certification_id']:null);}}}
}
